package net.officefloor.hq.app.clients;

import java.util.Comparator;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/** Turns a refused client into a problem response whose detail says what is wrong. */
@RestControllerAdvice(assignableTypes = ClientController.class)
public class ClientErrors {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail invalid(MethodArgumentNotValidException e) {
        String detail = e.getBindingResult().getFieldErrors().stream()
                .sorted(Comparator.comparing(f -> f.getField().equals("name") ? 0 : 1))
                .map(f -> f.getDefaultMessage())
                .distinct()
                .reduce((a, b) -> a + " " + b)
                .orElse("The client is not valid.");
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, detail);
    }

    @ExceptionHandler(ClientRejectedException.class)
    public ProblemDetail rejected(ClientRejectedException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }
}
package net.officefloor.hq.app.clients;

import org.springframework.data.jpa.repository.JpaRepository;

public interface ClientRepository extends JpaRepository<Client, Long> {

    boolean existsByEmailIgnoreCase(String email);
}
# Test launch only (bin/start): include the reason in error bodies, so a refused /__test__/seed
# names the field it cannot store.
spring.web.error.include-message=always
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema (base has no domain migrations). JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

